using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool definitions ---

class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static string SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
        var results = query.ToLowerInvariant() switch
        {
            var q when q.Contains("artificial intelligence") || q.Contains(" ai ") || q.Contains("ai") =>
                """
                1. "Artificial Intelligence: A Modern Approach" - AI is the study of agents that perceive their environment and take actions to maximize success. Key subfields include machine learning, natural language processing, computer vision, and robotics.
                2. Recent advances (2025-2026): Large language models have become multimodal, agentic AI systems are being deployed in enterprise workflows, and AI regulation frameworks are being adopted globally.
                3. Market analysis: The global AI market is projected to reach $900 billion by 2027, driven by generative AI adoption across industries.
                """,
            var q when q.Contains("climate") || q.Contains("global warming") =>
                """
                1. NASA Climate Report 2026: Global temperatures have risen 1.2°C above pre-industrial levels. Arctic ice loss continues to accelerate.
                2. Renewable energy now accounts for 45% of global electricity generation, up from 30% in 2022.
                3. The Paris Agreement targets remain challenging, with most nations behind on their pledges.
                """,
            var q when q.Contains("quantum computing") =>
                """
                1. Quantum computing uses qubits that can exist in superposition, enabling parallel computation for certain problem classes.
                2. IBM and Google have demonstrated quantum advantage for specific optimization problems in 2025-2026.
                3. Practical applications emerging: drug discovery, financial modeling, cryptography, and materials science.
                """,
            _ =>
                $"""
                1. General information about "{query}": This is an active area of research with multiple ongoing studies.
                2. Recent publications discuss new methodologies and frameworks related to {query}.
                3. Industry experts suggest significant developments expected in the coming years.
                """
        };

        return $"Web search results for '{query}':\n{results}";
    }
}

class NoteTakingTool
{
    private static readonly List<string> _notes = [];

    [Description("Saves a research note for later use in the summary. Use this to record key findings.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved (total notes: {_notes.Count}).";
    }

    [Description("Retrieves all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return "Saved notes:\n" + string.Join("\n", _notes.Select((n, i) => $"  [{i + 1}] {n}"));
    }
}

// --- Main program ---

var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in artificial intelligence";

Console.WriteLine("Research Agent Starting...");
Console.WriteLine($"Topic: {topic}");
Console.WriteLine(new string('-', 60));

// Configure the AI client with tool support
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Register tools
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.SearchWeb),
        AIFunctionFactory.Create(NoteTakingTool.SaveNote),
        AIFunctionFactory.Create(NoteTakingTool.GetNotes),
    ]
};

// System prompt defining the agent's behavior
var messages = new List<ChatMessage>
{
    new(ChatRole.System,
        """
        You are a research agent. Your job is to research a topic thoroughly and produce a clear summary.

        Follow this process:
        1. Search the web for information about the topic (perform 2-3 searches with different angles).
        2. Save important findings as notes using the note-taking tool.
        3. Retrieve your notes and synthesize them into a well-structured summary.

        Always use your tools — do not make up information. Be thorough but concise.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

Console.WriteLine("\nAgent is researching...\n");

// Run the agent loop — the FunctionInvocation middleware handles tool calls automatically
var response = await client.GetChatResponseAsync(messages, chatOptions);

Console.WriteLine("=== Research Summary ===\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n" + new string('=', 60));
Console.WriteLine("Research complete.");

